export const legacyOracleSources={"pipe":"\"\"\"Independent rectangular run/bend/run oracle. Standalone under python3 -I; no product imports.\"\"\"\nimport itertools,json,math,sys\nfrom fractions import Fraction as F\nTOL=1e-9\ndef near(a,b,tol,label):\n    assert math.isfinite(a)and math.isfinite(b),(label,'nonfinite',a,b)\n    assert abs(a-b)<=tol,(label,a,b,abs(a-b),tol)\ndef vecnear(a,b,label):\n    assert len(a)==len(b)\n    for k,(x,y)in enumerate(zip(a,b)):near(x,y,TOL,label+' '+str(k))\ndef pins(actual,expected,label):\n    assert len(actual)==len(expected),(label,'count',len(actual),len(expected))\n    remaining=list(expected)\n    for p in actual:\n        found=[i for i,q in enumerate(remaining)if max(abs(x-y)for x,y in zip(p,q))<=TOL]\n        assert len(found)==1,(label,'unmatched or ambiguous',p,remaining)\n        remaining.pop(found[0])\n    assert not remaining\ndef run(data):\n    doc=data['doc'];rd=data['read'];L1=data['run1'];depth=data['depth'];L2=data['run3']\n    assert(L1,depth,L2)in((12,2,12),(18,2,12),(18,4,12),(18,4,16))\n    a=F(2);b=F(depth,2);cy=b-1;R=F(10);A=4*a*b;alpha=math.pi/2;q=R+a*a/(3*R);D=L1+float(R)*alpha+L2\n    sk,sweep=doc['nodes'];path=[{'kind':'straight','length':L1},{'kind':'bend','radius':10,'angle':90,'toward':'x'},{'kind':'straight','length':L2}]\n    assert sk=={'kind':'sketch','profile':'rectangle','min':[-2,-1],'max':[2,depth-1],'sideTags':{'outer':['e1','e2','e3','e4']},'id':'n0'}\n    assert sweep=={'kind':'sweep','sketch':0,'path':path,'id':'n1'}and doc['nextId']==2 and doc['outputs']=={'b1':{'node':1,'side':'solid'}}\n    assert rd['ok']is True and rd['nodeVersion']=='22.19.0'and rd['bodyCount']==1 and rd['outputId']=='n1'and rd['bodyKey']=='b1'\n    assert rd['kernelSweep']['kind']=='sweep'and rd['kernelSweep']['sketch']=='n0'and rd['kernelSweep']['path']==path\n    assert rd['source']=={'family':'sweep','id':'n1'}and rd['check']['valid']is True and rd['nativeCounts']=={'vertices':16,'edges':28,'faces':14,'shells':1}\n    # Integrate dV=rho d(rho) dy dphi over rectangular rho8..12,y=cy-b..cy+b.\n    # q=(integral rho^2 dA)/(integral rho dA)=R+a^2/(3R); this is not a spine-only centroid.\n    volume=float(A)*D\n    X=float(R*R)*alpha-float(R*q)+float(F(L2)*(R+F(L2,2)))\n    Z=float(F(L1*L1,2))+float(R)*alpha*L1+float(R*q)+float(F(L2)*(L1+R))\n    centroid=[X/D,float(cy),Z/D];bounds={'min':[-2,-1,0],'max':[10+L2,depth-1,L1+12]}\n    deltas={}\n    for key in('mass','brepMass'):\n        m=rd[key];assert m['method']!='tessellated','mesh mass forbidden';near(m['volume'],volume,TOL*volume,key+' volume');vecnear(m['centroid'],centroid,key+' centroid')\n        deltas[key]={'volume':abs(m['volume']-volume),'centroid':max(abs(x-y)for x,y in zip(m['centroid'],centroid))}\n    for key in('min','max'):vecnear(rd['bounds'][key],bounds[key],'native bounds '+key)\n    corners=[[-2,-1],[2,-1],[2,depth-1],[-2,depth-1]]\n    def point(station,k):\n        x,y=corners[k%4]\n        if station==0:return[x,y,0]\n        if station==1:return[x,y,L1]\n        return[10+(L2 if station==3 else 0),y,L1+10-x]\n    vertices=[point(station,k)for station,k in itertools.product(range(4),range(4))]\n    pins(rd['vertices'],vertices,'sixteen native construction-station pins')\n    faceExpect={'n1.s0.bottom':[point(0,k)for k in range(4)],'n1.s2.top':[point(3,k)for k in range(4)]}\n    for piece in range(3):\n        for edge in range(4):faceExpect[f'n1.s{piece}.side[e{edge+1}]']=[point(station,k)for station in(piece,piece+1)for k in(edge,(edge+1)%4)]\n    assert len(rd['faces'])==14 and{f['name']for f in rd['faces']}==set(faceExpect),'exact selected surviving source-face witnesses'\n    for face in rd['faces']:\n        name=face['name'];pins(face['vertices'],faceExpect[name],'native face boundary '+name)\n        for probe in face['probes']:\n            p=probe['point'];normal=probe['normal']\n            if name in('n1.s1.side[e2]','n1.s1.side[e4]'):\n                radius=8 if name.endswith('[e2]')else 12;sign=-1 if radius==8 else 1;dx=p[0]-10;dz=p[2]-L1\n                near(math.hypot(dx,dz),radius,TOL,'native cylindrical bend radius '+name);assert-1-TOL<=p[1]<=depth-1+TOL\n                theta=math.atan2(dz,-dx);assert-TOL<=theta<=alpha+TOL,'native +X quarter bend orientation'\n                wantnormal=[sign*dx/radius,0,sign*dz/radius]\n            else:\n                if name=='n1.s0.bottom':axis=2;value=0;wantnormal=[0,0,-1]\n                elif name=='n1.s2.top':axis=0;value=10+L2;wantnormal=[1,0,0]\n                else:\n                    piece=int(name[4]);edge=int(name[-2]);\n                    if edge in(1,3):axis=1;value=-1 if edge==1 else depth-1;wantnormal=[0,-1 if edge==1 else 1,0]\n                    elif piece==0:axis=0;value=2 if edge==2 else -2;wantnormal=[1 if edge==2 else -1,0,0]\n                    else:assert piece==2;axis=2;value=L1+10+(-2 if edge==2 else 2);wantnormal=[0,0,-1 if edge==2 else 1]\n                near(p[axis],value,TOL,'native plane carrier '+name)\n            vecnear(normal,wantnormal,'native outward normal '+name)\n    for e in rd['edges']:\n        assert e['degree']in(1,2)\n        if e['degree']==1:\n            start,end=e['endpoints']\n            for t,p in zip((0,.25,.5,.75,1),e['samples']):vecnear(p,[start[k]+t*(end[k]-start[k])for k in range(3)],'native straight boundary interpolation')\n    curved=[e for e in rd['edges']if e['degree']==2];assert len(curved)==4\n    circles={frozenset(['n1.s1.side[e1]','n1.s1.side[e2]']):(-1,8),frozenset(['n1.s1.side[e2]','n1.s1.side[e3]']):(depth-1,8),\n        frozenset(['n1.s1.side[e3]','n1.s1.side[e4]']):(depth-1,12),frozenset(['n1.s1.side[e1]','n1.s1.side[e4]']):(-1,12)}\n    observed=[]\n    for e in curved:\n        pair=frozenset(e['adjacentFaces']);assert pair in circles;observed.append(pair);y,radius=circles[pair]\n        for p in e['samples']:\n            near(p[1],y,TOL,'native arc axial pin');near(math.hypot(p[0]-10,p[2]-L1),radius,TOL,'native bend arc radial pin')\n            theta=math.atan2(p[2]-L1,10-p[0]);assert-TOL<=theta<=alpha+TOL\n    assert set(observed)==set(circles)\n    seamWitnesses=[]\n    for join in(1,2):\n        for edge in range(4):\n            pair={f'n1.s{join-1}.side[e{edge+1}]',f'n1.s{join}.side[e{edge+1}]'};hits=[e for e in rd['edges']if set(e['adjacentFaces'])==pair]\n            assert len(hits)==1 and hits[0]['degree']==1,('whole-face glue seam',pair,hits)\n            pins(hits[0]['endpoints'],[point(join,edge),point(join,(edge+1)%4)],'native shared-face seam pins')\n            seamWitnesses.append(hits[0]['name'])\n    return{'status':'PASS','productImports':0,'geometrySource':'current strict native B-rep, no mesh truth','run1':L1,'depth':depth,'run3':L2,'volume':volume,'centroid':centroid,'bounds':bounds,\n        'exactRectangularRadialMean':str(q),'constructionPieces':3,'nativeSolidBodies':1,'nativeCounts':rd['nativeCounts'],'sharedFaceSeamWitnesses':seamWitnesses,\n        'nativeLimits':{'volumeRelative':TOL,'centroidAbsolute':TOL,'boundsAbsolute':TOL,'nativeBoundaryPinsAbsolute':TOL,'outwardUnitNormalAbsolute':TOL},'deltas':deltas,\n        'scopeBoundary':'one non-overlapping rectangular native Pipe profile; no faceted sweep-curve, new bend/admission, arbitrary path/frame, fitter/thicken/NURBS or inertia claim'}\nif __name__=='__main__':print(json.dumps(run(json.load(sys.stdin)),indent=2))\n","loft":"\"\"\"Independent finite no-guide rectangle Loft oracle; standalone under python3 -I.\nNo product imports. Expected moments come from exact polynomial slice integration.\nNative carrier coefficients, directed trim loops and edge endpoints are checked separately.\n\"\"\"\nimport json, math, sys\nfrom fractions import Fraction as F\nTOL = 1e-9\ndef near(a,b,tol,label):\n    assert math.isfinite(a) and math.isfinite(b),(label,'nonfinite',a,b)\n    assert abs(a-b)<=tol,(label,a,b,abs(a-b),tol)\ndef vec(a,b,label):\n    assert len(a)==len(b)\n    for i,(x,y) in enumerate(zip(a,b)):near(x,y,TOL,label+' '+str(i))\ndef pins(actual,expected,label):\n    assert len(actual)==len(expected),(label,'count',len(actual),len(expected))\n    rest=list(expected)\n    for p in actual:\n        matches=[i for i,q in enumerate(rest) if len(p)==len(q) and max(abs(x-y) for x,y in zip(p,q))<=TOL]\n        assert len(matches)==1,(label,'unmatched or ambiguous',p,rest)\n        rest.pop(matches[0])\n    assert not rest\ndef integral(coeff):\n    return sum((c/F(i+1) for i,c in enumerate(coeff)),F(0))\ndef multiply(a,b):\n    out=[F(0)]*(len(a)+len(b)-1)\n    for i,x in enumerate(a):\n        for j,y in enumerate(b):out[i+j]+=x*y\n    return out\ndef expected_doc(H):\n    return {'format':'barocss-cad-model','schema':3,'units':'mm','parameters':{'W':70},'nodes':[\n        {'kind':'sketch','profile':'rectangle','min':[0,0],'max':[{'parameter':'W'},40],'sideTags':{'outer':['e1','e2','e3','e4']},'id':'n0'},\n        {'kind':'sketch','profile':'rectangle','min':[10,10],'max':[{'parameter':'W'},30],'plane':{'origin':[0,0,30],'normal':[0,0,1],'xAxis':[1,0,0]},'sideTags':{'outer':['e1','e2','e3','e4']},'id':'n1'},\n        {'kind':'sketch','profile':'loop','segments':[{'kind':'line','start':p} for p in [[0,0],[60,0],[60,40],[0,40]]],'id':'n2'},\n        {'kind':'sketch','profile':'loop','segments':[{'kind':'line','start':p} for p in [[10,10],[60,10],[60,30],[10,30]]],'id':'n3'},\n        {'kind':'loft','sections':[{'sketch':2,'z':0},{'sketch':3,'z':H}],'from':[0,1],'id':'n4'}],\n        'outputs':{'b4':{'node':4,'side':'solid'}},'nextId':5}\ndef run(data):\n    H=data['height'];doc=data['doc'];rd=data['read'];assert H in (30,40,50) and not isinstance(H,bool)\n    assert doc==expected_doc(H),'only Section2 height may change; original bound sketches and copied numeric sections stay exact'\n    assert rd['ok'] is True and rd['height']==H and rd['nodeVersion']=='22.19.0'\n    assert (rd['bodyCount'],rd['bodyKey'],rd['outputId'])==(1,'b4','n4')\n    assert rd['source']=={'family':'loft','id':'n4'} and rd['kernelLoft']['kind']=='loft'\n    assert rd['kernelLoft']['sections']==[{'sketch':'n2','z':0},{'sketch':'n3','z':H}]\n    assert rd['check']['valid'] is True\n    assert rd['nativeCounts']=={'vertices':8,'edges':12,'faces':6,'shells':1,'loops':6,'coedges':24}\n    # t=z/H, width=60-10t, depth=40-20t, slice centre=(30+5t,20,Ht).\n    # This integrates the actual finite rectangular taper, with no mesh/mass helper as authority.\n    area=multiply([F(60),F(-10)],[F(40),F(-20)]);I=integral(area)\n    exactV=F(H)*I;exactC=[integral(multiply(area,[F(30),F(5)]))/I,F(20),F(H)*integral(multiply(area,[F(0),F(1)]))/I]\n    assert exactV==F(5000*H,3) and exactC==[F(643,20),F(20),F(43*H,100)]\n    V=float(exactV);C=list(map(float,exactC));bounds={'min':[0,0,0],'max':[60,40,H]};deltas={}\n    for key in ('mass','brepMass'):\n        m=rd[key];assert m['method']!='tessellated';near(m['volume'],V,TOL*V,key+' volume');vec(m['centroid'],C,key+' centroid')\n        deltas[key]={'volume':abs(m['volume']-V),'centroid':max(abs(x-y) for x,y in zip(m['centroid'],C))}\n    for k in ('min','max'):vec(rd['bounds'][k],bounds[k],'native trimmed bounds '+k)\n    base=[[0,0,0],[60,0,0],[60,40,0],[0,40,0]];top=[[10,10,H],[60,10,H],[60,30,H],[10,30,H]]\n    pins(rd['vertices'],base+top,'eight native corner pins')\n    facePins={'n4.bottom':base,'n4.top':top}\n    for i in range(4):facePins['n4.side'+str(i)]=[base[i],base[(i+1)%4],top[i],top[(i+1)%4]]\n    # Every pole lies on its independently derived carrier plane. Normalised distances use mm.\n    planes={'n4.bottom':([0,0,-1],0),'n4.top':([0,0,1],H),'n4.side0':([0,-H,10],0),\n            'n4.side1':([1,0,0],60),'n4.side2':([0,H,10],40*H),'n4.side3':([-H,0,10],0)}\n    faces={f['id']:f for f in rd['faces']};assert len(faces)==6 and {f['name'] for f in faces.values()}==set(facePins)\n    def on_plane(name,p,label):\n        n,d=planes[name];length=math.hypot(*n);near(sum(x*y for x,y in zip(n,p))/length,d/length,TOL,label)\n    for face in faces.values():\n        name=face['name'];pins(face['vertices'],facePins[name],'native face trim corners '+name)\n        assert (face['degreeU'],face['degreeV'])==(1,1)\n        assert len(face['controlPoints'])==2 and all(len(row)==2 for row in face['controlPoints'])\n        assert len(face['weights'])==2 and all(len(row)==2 and all(math.isfinite(w) and w>0 for w in row) for row in face['weights'])\n        for row in face['controlPoints']:\n            for p in row:on_plane(name,p,'whole native bilinear carrier coefficient '+name)\n        n,d=planes[name];length=math.hypot(*n);normal=[x/length for x in n]\n        for p in face['probes']:on_plane(name,p['point'],'native carrier probe '+name);vec(p['normal'],normal,'native outward normal '+name)\n    edges={e['id']:e for e in rd['edges']};assert len(edges)==12\n    expectedEdges=[]\n    for station,cap in ((base,'n4.bottom'),(top,'n4.top')):\n        for i in range(4):expectedEdges.append((frozenset((cap,'n4.side'+str(i))),[station[i],station[(i+1)%4]]))\n    for i in range(4):expectedEdges.append((frozenset(('n4.side'+str((i-1)%4),'n4.side'+str(i))),[base[i],top[i]]))\n    for pair,want in expectedEdges:\n        hits=[e for e in edges.values() if frozenset(e['adjacentFaces'])==pair];assert len(hits)==1,('native edge-face pair',list(pair),hits)\n        edge=hits[0];assert edge['degree']==1 and len(edge['controlPoints'])==2 and len(edge['weights'])==2\n        assert all(math.isfinite(w) and w>0 for w in edge['weights']);pins(edge['endpoints'],want,'native cap/ruling endpoints');pins(edge['controlPoints'],want,'native whole straight edge coefficients')\n        start,end=edge['endpoints']\n        for t,p in zip((0,.25,.5,.75,1),edge['samples']):\n            vec(p,[start[k]+t*(end[k]-start[k]) for k in range(3)],'native represented straight edge')\n            for name in pair:on_plane(name,p,'shared edge lies on both native carriers')\n    # Independent topological binding: each outer trim closes, uses its actual face pins once,\n    # and each edge has exactly two opposite, mutual twin uses in one closed shell.\n    verts={v['id']:v['point'] for v in rd['vertexRecords']};assert len(verts)==8\n    loops={l['id']:l for l in rd['loops']};coedges={c['id']:c for c in rd['coedges']};assert len(loops)==6 and len(coedges)==24\n    used=[];edgeUses={eid:[] for eid in edges};loopUses=[]\n    def ends(c):\n        e=edges[c['edge']];return e['vertices'] if c['sense']=='forward' else list(reversed(e['vertices']))\n    for face in faces.values():\n        assert len(face['loops'])==1;lid=face['loops'][0];loop=loops[lid];loopUses.append(lid)\n        assert loop['face']==face['id'] and loop['kind']=='outer' and len(loop['coedges'])==4\n        starts=[]\n        for i,cid in enumerate(loop['coedges']):\n            c=coedges[cid];n=coedges[loop['coedges'][(i+1)%4]];prev=coedges[loop['coedges'][(i+3)%4]];used.append(cid)\n            assert c['sense'] in ('forward','reversed') and c['loop']==lid and c['next']==n['id'] and c['prev']==prev['id']\n            twin=coedges[c['twin']];assert twin['twin']==cid and twin['edge']==c['edge'] and twin['sense']!=c['sense']\n            assert ends(c)[1]==ends(n)[0];edgeUses[c['edge']].append(c);starts.append(verts[ends(c)[0]])\n            assert face['name'] in edges[c['edge']]['adjacentFaces']\n        pins(starts,facePins[face['name']],'directed reciprocal trim ring')\n        normal=planes[face['name']][0];areaVector=[0.,0.,0.]\n        for i,p in enumerate(starts):\n            q=starts[(i+1)%4]\n            areaVector[0]+=p[1]*q[2]-p[2]*q[1];areaVector[1]+=p[2]*q[0]-p[0]*q[2];areaVector[2]+=p[0]*q[1]-p[1]*q[0]\n        assert sum(x*y for x,y in zip(areaVector,normal))>0,'trim traversal agrees with independently expected outward normal'\n    assert len(set(loopUses))==6 and len(set(used))==24\n    for eid,uses in edgeUses.items():\n        assert len(uses)==2 and uses[0]['twin']==uses[1]['id'] and uses[1]['twin']==uses[0]['id']\n        actualFaces={faces[loops[c['loop']]['face']]['name'] for c in uses};assert actualFaces==set(edges[eid]['adjacentFaces']) and len(actualFaces)==2\n        vec([verts[k] for k in edges[eid]['vertices']][0],edges[eid]['endpoints'][0],'edge start record binding')\n        vec([verts[k] for k in edges[eid]['vertices']][1],edges[eid]['endpoints'][1],'edge end record binding')\n    return {'status':'PASS','height':H,'productImports':0,'geometrySource':'current strict native BRep, no mesh truth','exactVolume':str(exactV),'exactCentroid':list(map(str,exactC)),\n        'volume':V,'centroid':C,'bounds':bounds,'nativeCounts':rd['nativeCounts'],'deltas':deltas,'reciprocalTrimLoops':6,'reciprocalEdgePairs':12,\n        'nativeLimits':{'volumeRelative':TOL,'centroidAbsolute':TOL,'boundsAbsolute':TOL,'boundaryPinsAbsolute':TOL,'normalAbsolute':TOL},\n        'boundary':'ordinary two copied numeric rectangles, existing Section2 height only; no live W source, guided Loft, arbitrary sections, mesh or inertia claim'}\nif __name__=='__main__':print(json.dumps(run(json.load(sys.stdin)),indent=2))\n"};
